def tokenize(text):
    tokens = []
    i = 0
    while i < len(text):
        if text[i].isspace():
            i += 1
            continue
        elif text[i] in '()[]{}':
            tokens.append(text[i])
            i += 1
        else:
            start = i
            while i < len(text) and not text[i].isspace() and text[i] not in '()[]{}':
                i += 1
            tokens.append(text[start:i])
    return tokens

